using System.Net;using System.Net.Http.Json;using System.Text.Json;using Berbergelsin.Api.Data;using Berbergelsin.Api.Entities;using Berbergelsin.Api.Enums;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Xunit;
namespace Berbergelsin.Api.Tests;
public sealed class RatingLifecycleTests{
 [Fact]public async Task Customer_rates_completed_own_request_and_duplicate_conflicts(){using var f=new RequestApiFactory();f.Seed();var id=SeedRequest(f,RequestStatus.Completed);var c=f.Client(f.ClientId,"Musteri");Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="  Harika  "})).StatusCode);var dup=await c.PostAsJsonAsync($"/api/requests/{id}/rate",new{score=4,comment="x"});Assert.Equal(HttpStatusCode.Conflict,dup.StatusCode);using var s=f.Services.CreateScope();Assert.Equal("Harika",(await s.ServiceProvider.GetRequiredService<AppDbContext>().Ratings.SingleAsync()).Comment);}
 [Fact]public async Task Pending_other_and_barber_are_rejected(){using var f=new RequestApiFactory();f.Seed();var id=SeedRequest(f,RequestStatus.Pending);Assert.Contains("rating_request_not_completed",await (await f.Client(f.ClientId,"Musteri").PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="x"})).Content.ReadAsStringAsync());Assert.Equal(HttpStatusCode.Forbidden,(await f.Client(f.BarberUserId,"Berber").PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="x"})).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await f.Client(f.OtherClientId,"Musteri").PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="x"})).StatusCode);}
 [Fact]public async Task Owner_updates_with_version_then_soft_deletes_idempotently(){using var f=new RequestApiFactory();f.Seed();var id=SeedRequest(f,RequestStatus.Completed);var c=f.Client(f.ClientId,"Musteri");await c.PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="x"});Guid ratingId;string version;using(var s=f.Services.CreateScope()){var r=await s.ServiceProvider.GetRequiredService<AppDbContext>().Ratings.SingleAsync();ratingId=r.Id;version=r.Version.ToString();}Assert.Equal(HttpStatusCode.OK,(await c.PutAsJsonAsync($"/api/ratings/{ratingId}",new{score=3,comment="Güncel",version})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.DeleteAsync($"/api/ratings/{ratingId}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.DeleteAsync($"/api/ratings/{ratingId}")).StatusCode);using var scope=f.Services.CreateScope();Assert.True((await scope.ServiceProvider.GetRequiredService<AppDbContext>().Ratings.SingleAsync()).IsDeleted);}
 [Fact]public async Task Other_customer_reports_once_but_owner_cannot_report(){using var f=new RequestApiFactory();f.Seed();var id=SeedRequest(f,RequestStatus.Completed);await f.Client(f.ClientId,"Musteri").PostAsJsonAsync($"/api/requests/{id}/rating",new{score=5,comment="x"});Guid rid;using(var s=f.Services.CreateScope())rid=(await s.ServiceProvider.GetRequiredService<AppDbContext>().Ratings.SingleAsync()).Id;var other=f.Client(f.OtherClientId,"Musteri");Assert.Equal(HttpStatusCode.OK,(await other.PostAsJsonAsync($"/api/ratings/{rid}/report",new{reasonCode="spam",description="x"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await other.PostAsJsonAsync($"/api/ratings/{rid}/report",new{reasonCode="spam",description="x"})).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await f.Client(f.ClientId,"Musteri").PostAsJsonAsync($"/api/ratings/{rid}/report",new{reasonCode="abuse",description="x"})).StatusCode);}
 static Guid SeedRequest(RequestApiFactory f,RequestStatus status){using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var id=Guid.NewGuid();db.ServiceRequests.Add(new ServiceRequest{Id=id,ClientUserId=f.ClientId,BarberProfileId=f.ProfileId,Status=status,RequestedTime=DateTimeOffset.UtcNow.AddDays(-1),ScheduledEndTime=DateTimeOffset.UtcNow.AddDays(-1).AddHours(1),CreatedAt=DateTime.UtcNow.AddDays(-1),UpdatedAt=DateTime.UtcNow,CreatedBy=f.ClientId});db.SaveChanges();return id;}}
